/** Runtime adapter; schema.d.ts is generated by openapi-typescript, never edited by hand. */
import createClient, { type ClientOptions } from 'openapi-fetch';
import type { paths } from './schema.js';
export type { paths, components, operations } from './schema.js';
/** Separate clients/base URLs are required for the business and platform deployments. */
export function createQuincaiClient(options: ClientOptions) {
  return createClient<paths>(options);
}
